local Serial = require "actions/Serial"
local Do = require "actions/Do"
local MessageBox = require "actions/MessageBox"

return function(self)
    return Serial {
        MessageBox {
            message = "<- Huts & Gardens\n\n{p50}-> War Alcoves & Ring Grotto",
            blocking = true
        },
        Do(function()
            self.scene.player.hidekeyhints[tostring(self)] = nil
        end)
    }
end

local Serial = require "actions/Serial"
local Do = require "actions/Do"
local MessageBox = require "actions/MessageBox"
local Menu = require "actions/Menu"
local Action = require "actions/Action"
local BlockPlayer = require "actions/BlockPlayer"

local Transform = require "util/Transform"
local Layout = require "util/Layout"

return function(self)
    return BlockPlayer { Menu {
            layout = Layout {
                {Layout.Text("Check for Power Ring?"), selectable = false},
                {Layout.Text("Yes"), choose = function(menu)
                    menu:close()
                    if GameState:hasItem("PowerRing") or GameState:isFlagSet("got_ring") then
                        self.scene:run {
                            menu,
                            MessageBox {
                                message = "It doesn't look like it's ready...",
                                blocking = true
                            }
                        }
                    else
                        GameState:setFlag("got_ring")
                        GameState:grantItem(require("data/items/PowerRing"), 1)
                        self.scene:run {
                            menu,
                            MessageBox {
                                message = "You received a Power Ring!",
                                blocking = true,
                                sfx = "levelup"
                            }
                        }
                    end
                end},
                {Layout.Text("No"), choose = function(menu) menu:close() end},
            },
            cancellable = true,
            transform = Transform(love.graphics.getWidth()/2, love.graphics.getHeight()/2 + 30),
            selectedRow = 2
        },
        Do(function()  self.scene.player.hidekeyhints[tostring(self)] = nil end)
    }
end

local BlockPlayer = require "actions/BlockPlayer"
local Do = require "actions/Do"
local MessageBox = require "actions/MessageBox"

return function(self)
    GameState:grantItem(require("data/items/YellowLeaf"), 1)
    return BlockPlayer {
        Do(function() self:permanentRemove() end),
        MessageBox {message = "You received a Yellow Leaf!", sfx = "levelup", textSpeed = 7}
    }
end

